/* src/app/themes/github-css/style.css */
.sub-title {
  opacity: 0.8;
}
.container-1440 {
  max-width: 1400px;
  margin: 0 auto;
}
.container-1200 {
  max-width: 1170px;
  margin: 0 auto;
}
.feature-list {
  padding: 0;
  list-style: none;
}
.feature-list li span {
  position: absolute;
  left: 0;
}
.icn-success {
  color: #59D99D;
}
.feature-list li {
  position: relative;
  padding-left: 23px;
  margin-bottom: 8px;
  color: #434456;
}
.icn-inline {
  font-size: 18px;
  position: relative;
  top: 3px;
  margin-right: 5px;
}
.bg-light-purple {
  background-color: #f8f9fd;
}
.demo {
  height: 100%;
  display: flex;
}
.nav-heading {
  text-transform: uppercase;
  font-size: 12px;
  padding: 10px 0;
  color: rgba(0, 0, 0, .6);
  border-bottom: 1px solid rgba(0, 0, 0, .15);
}
.nav-list {
  padding: 20px 0;
}
.nav-item {
  margin: 5px 0;
  padding: 10px 20px;
  color: rgba(0, 0, 0, .6);
  cursor: pointer;
}
.nav-item.selected {
  color: #FFFFFF;
  background: #6957DA;
  border-radius: 4px;
  overflow: hidden;
  box-shadow: 0 4px 9px 0 rgba(23, 28, 33, .06);
  cursor: auto;
}
.item-desc {
  opacity: 0.8;
  line-height: 120%;
}
.header-link {
  color: rgba(0, 0, 0, 0.6);
}
.side-nav .nav-list .nav-item:hover {
  color: #FFFFFF;
  background: #6957DA;
  border-radius: 4px;
  overflow: hidden;
  box-shadow: 0 4px 9px 0 rgba(23, 28, 33, .06);
}
.side-nav .nav-list {
  height: 550px;
  overflow-y: scroll;
}
.chart-view .card-body {
  display: flex;
  align-items: center;
  justify-content: space-around;
  min-height: 350px;
}
.chart-wrapper-inner {
  width: 100%;
  height: 100%;
  text-align: center;
}
.code-view .card,
.code-view {
  overflow: hidden;
  border-radius: 4px;
}
.code-view {
  width: 100%;
  margin-bottom: 15px;
  box-shadow: 0 2px 4px 0 rgba(104, 105, 128, .3);
}
.code-view .code-panel {
  background: #22263b;
  margin: 0 !important;
}
#chartCode {
  width: 100%;
}
.codeMirrorDiv .CodeMirror {
  height: auto !important;
  padding: 8px;
}
.code-view .code-panel-header {
  padding: 10px 15px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.code-view .code-panel-view {
  padding: 0;
  background: #22263b;
  max-height: 300px;
  height: 100%;
  overflow: scroll;
}
.ref-link {
  font-weight: 600;
}
.btn-code {
  border-radius: 0;
  background: #03040B;
  color: #73748C;
}
.btn-code.selected {
  border-radius: 0;
  background: #22263B;
  color: #FFFFFF;
}
#chart-code {
  width: 100%;
}
.chart-selector {
  max-width: 320px;
  width: 100%;
  margin-bottom: 24px;
}
.base-dropdown .selector {
  width: 100%;
  display: block;
  padding: 12px 35px 12px 15px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}
.base-dropdown {
  display: inline-block;
  border: 1px solid rgba(62, 57, 107, .13);
  border-radius: 4px;
  position: relative;
}
.base-dropdown .placeholder {
  position: absolute;
  top: -10px;
  left: 12px;
  font-size: 12px;
  font-weight: 600;
  padding: 0 3px;
  color: #9f9fb9;
  background: #f9f9fc;
  pointer-events: none;
}
.base-dropdown .caret {
  position: absolute;
  top: 10px;
  right: 12px;
  pointer-events: none;
}
.foot-item {
  color: #9FA0B7;
  font-weight: 300 !important;
}
#navbar {
  height: 64px;
}
#footbar {
  height: 100px;
  background-color: #1B192F;
}
body {
  overflow-x: hidden;
}
.modal {
  display: none;
  position: fixed;
  z-index: 1;
  padding-top: 100px;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  overflow: auto;
  background-color: rgb(0, 0, 0);
  background-color: rgba(0, 0, 0, 0.5);
}
.modal-content {
  background-color: #fefefe;
  margin: auto;
  padding: 20px;
  border: 1px solid #888;
  width: 80%;
}
.close {
  color: #aaaaaa;
  float: right;
  font-size: 28px;
  font-weight: bold;
}
.close:hover,
.close:focus {
  color: #000;
  text-decoration: none;
  cursor: pointer;
}
@media (min-width:768px) {
  .navbar {
    padding: .5rem;
  }
}
@media (min-width:992px) {
  .navbar .navbar-nav .nav-item {
    margin-right: 1rem;
  }
}
@media (min-width:1200px) {
  .navbar {
    padding: .6rem 4%;
  }
  .navbar .navbar-nav .nav-item {
    margin-right: 1.4rem;
  }
}
/*# sourceMappingURL=style.css.map */
